"""Pure shared gates from completed RAM trial; importing performs no I/O."""
AI_PREFLIGHT = "\nimport pathlib,json,subprocess,platform,os,zlib,struct,hashlib\nP=pathlib.Path\nassert platform.release()=='5.15.140'\nassert os.access('/bin/systemctl',os.X_OK)\nassert P('/usr/bin/fw_setenv').resolve()==P('/usr/bin/fw_printenv').resolve(), 'Unexpected fw_setenv target'\nassert hashlib.sha256(P('/usr/bin/fw_printenv').read_bytes()).hexdigest()=='3c1c7952e7b8877c5897bcbdf4125fb43d9bd5252e38c331aeaae02186557100','Environment tool/library differs from audited build'\nassert hashlib.sha256(P('/usr/lib/libubootenv.so.0.3.5').read_bytes()).hexdigest()=='1307197984043407b8464e5013d83d743e907726c72de6564668c1435cf68f61','Environment tool/library differs from audited build'\ndef c(args):\n p=subprocess.run(args,capture_output=True,timeout=8);assert p.returncode==0,(args,p.stderr.decode());return p.stdout.decode().strip()\nroot=c(['findmnt','-no','SOURCE,UUID','/']).split();assert root==['/dev/mmcblk0p13','e46de487-2d50-4bfb-9365-33ea9027d40e'],root\nkeys=['bootcmd','boot_slot','bootlimit','bootcount','upgrade_available','altbootcmd']\nenv=dict(x.split('=',1) for x in c(['fw_printenv']+keys).splitlines())\nassert env['bootcmd']=='bootmmc' and env['boot_slot']=='2' and env['bootlimit']=='3' and env['bootcount']=='0' and env['upgrade_available']=='0',env\nrows=[]\nfor dev in ['/dev/mmcblk0p6','/dev/mmcblk0p7']:\n with open(dev,'rb') as f:f.seek(0xff0000);b=f.read(0x10000)\n assert len(b)==0x10000 and zlib.crc32(b[5:])&0xffffffff==struct.unpack_from('<I',b)[0]\n fields=dict(x.split(b'=',1) for x in b[5:].split(b'\\0') if b'=' in x)\n rows.append((b[4],fields))\nif rows[0][0]==rows[1][0]:assert rows[0][1]==rows[1][1]\nactive=rows[0] if ((rows[0][0]-rows[1][0])&255)<128 else rows[1]\nassert all(active[1].get(k.encode(),b'').decode()==v for k,v in env.items())\nseen=active[1].get(b'leon_ai_guard_seen',b'').decode()\nif not globals().get('ALLOW_GUARD_MARKER',False):assert b'leon_ai_guard_seen' not in active[1]\n\nwith open('/dev/mmcblk0p17','rb') as f:f.seek(4096);misc=f.read(32).hex()\nassert misc=='0041424202000302000000080200000000000000000000000000000000000000',misc\ncfg=json.loads(P('/home/root/config.json').read_text());ssh=cfg['ssh_service'];assert ssh['state']=='enabled' and ssh['port']==22 and ssh['disallow_root_logins']==False\nbusy=[]\nfor q in P('/proc').iterdir():\n if q.name.isdigit():\n  try:\n   comm=(q/'comm').read_text().strip()\n   if any(w in comm.lower() for w in ['geekbench','fwupdate','abupdate','factory_reset','rescue_auto']):busy.append(comm)\n  except OSError:pass\nassert not busy,busy\nunits=['docker.service','avahi-daemon.service','systemd-networkd.service','usage-stats.service']\nhealth=c(['systemctl','is-active']+units).splitlines();assert health==['active']*len(units),dict(zip(units,health))\n# Stock starts both SysV and udev template supplicants. Either can own the device;\n# require exactly one actual owner, not a particular competing service name.\nowners=[]\nfor q in P('/proc').iterdir():\n if not q.name.isdigit():continue\n try:\n  if (q/'comm').read_text().strip()!='tee-supplicant':continue\n  for fd in (q/'fd').iterdir():\n   try:\n    if os.readlink(fd)=='/dev/teepriv0':owners.append(int(q.name))\n   except OSError:pass\n except OSError:pass\nassert len(set(owners))==1,owners\nprint(json.dumps({'boot_id':P('/proc/sys/kernel/random/boot_id').read_text().strip(),'uptime':P('/proc/uptime').read_text().strip(),'root':root,'env':env,'misc':misc,'ssh_state':ssh['state'],'busy':busy,'guard_seen':seen,'env_flags':[x[0] for x in rows],'services':dict(zip(units,health)),'tee_owner':owners}))\n"

BCM_PREFLIGHT = "\nimport pathlib,hashlib,os,json\nP=pathlib.Path\nassert hashlib.sha256(P('/usr/bin/asus').read_bytes()).hexdigest()=='2312c2fd8a7602429f22f382e2c117edfb9f68e4502893961d473da7bf9d280b'\nassert hashlib.sha256(P('/usr/libexec/asus/rc').read_bytes()).hexdigest()=='ddd02bc669cc1760cdca577178d9b4d9d4cd57d5674081d0fc20d7c4808955c2'\nselected=None\nfor folder in ['bin','sbin']:\n q=P('/usr/share/asus/commands')/folder/'service'\n if q.is_symlink():selected=q;break\nassert selected and selected.resolve()==P('/usr/libexec/asus/rc'),str(selected)\nassert selected.lstat().st_uid==0\nlevels={str(n):(P('/sys/class/leds')/('led_gpio_'+str(n))/'brightness').read_text().strip() for n in [16,21,6]}\nassert levels=={'16':'0','21':'0','6':'0'},levels\nfor n in [16,21,6]:assert '[none]' in (P('/sys/class/leds')/('led_gpio_'+str(n))/'trigger').read_text()\nprint(json.dumps({'boot_id':P('/proc/sys/kernel/random/boot_id').read_text().strip(),'uptime':P('/proc/uptime').read_text().strip(),'service_map':str(selected),'levels':levels}))\n"

def env_code(text, expected):
    return 'import pathlib,subprocess,tempfile,os,json,zlib,struct\ntext=' + repr(text) + '\nexpected=' + repr(expected) + "\nf=tempfile.NamedTemporaryFile(mode='w',prefix='leon-guard-',dir='/run',delete=False);path=f.name\ntry:\n os.chmod(path,0o600);f.write(text);f.close()\n p=subprocess.run(['/usr/bin/fw_setenv','-s',path],capture_output=True)\n assert p.returncode==0,p.stderr.decode()\n present={k:v for k,v in expected.items() if v!=''}\n p=subprocess.run(['fw_printenv']+list(present),capture_output=True,timeout=8);assert p.returncode==0,p.stderr.decode()\n actual=dict(x.split('=',1) for x in p.stdout.decode().splitlines());assert actual==present,(actual,present)\n rows=[]\n for dev in ['/dev/mmcblk0p6','/dev/mmcblk0p7']:\n  with open(dev,'rb') as f:f.seek(0xff0000);b=f.read(0x10000)\n  assert len(b)==0x10000 and zlib.crc32(b[5:])&0xffffffff==struct.unpack_from('<I',b)[0]\n  fields=dict(x.split(b'=',1) for x in b[5:].split(b'\\0') if b'=' in x)\n  rows.append((b[4],fields))\n if rows[0][0]==rows[1][0]:assert rows[0][1]==rows[1][1]\n active=rows[0] if ((rows[0][0]-rows[1][0])&255)<128 else rows[1]\n assert all((active[1].get(k.encode(),b'').decode()==v if v!='' else k.encode() not in active[1]) for k,v in expected.items())\n if 'leon_ai_guard_seen=\\n' in text:assert b'leon_ai_guard_seen' not in active[1]\n os.sync();print(json.dumps({'verified':actual,'both_env_crc_valid':True,'active_serial':active[0]}))\nfinally:os.unlink(path)\n"
